## 2.2.2. 利用 `fork` 实现进程间通信

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>

int main(int argc, char *argv[]) { 
    char* important_config = "important_config";

    // save the important config to a file
	FILE *important_config_file = fopen(important_config, "w");
	fprintf(important_config_file, "important_config");
	fclose(important_config_file);

    // open the important config file
	FILE *important_config_file_open = fopen(important_config, "r");
	if (important_config_file_open == NULL) {
		printf("Error opening important config file\n");
		exit(1);
	}

    // read the important config file
	char *important_config_file_read = fgets(important_config_file, 1000, important_config_file_open);
	fclose(important_config_file_open);

	printf("Important config file contents:\n%s\n", important_config_file_read);

    // close the important config file
	fclose(important_config_file);

    // fork a new process
	pid_t pid = fork();
	if (pid == -1) {
		printf("Error forking\n");
		exit(1);
	}
	if (pid == 0) {
		// child process
		printf("Child process\n");
		// close the important config file
		fclose(important_config_file);
		// remove the important config file
		remove(important_config);
		exit(0);
	}

	// parent process
	printf("Parent process\n");
	// close the important config file
	fclose(important_config_file);
	// remove the important config file
	remove(important_config);
	exit(0);
}
```

