### 2.2.2.2. 字符串截取

```c
#include <string.h>

int main(int argc, char *argv[]) {
    // get buffer size from argv
    int buffer_size = atoi(argv[1]);
    // allocate buffer
    char *buffer = (char *)malloc(buffer_size);
    // get string from argv
    char *str = argv[2];
    // get start index from argv
    int start_index = atoi(argv[3]);
    // get end index from argv
    int end_index = atoi(argv[4]);
    // get substring
    char *substring = strndup(str, end_index - start_index);
    // copy substring to buffer
    memcpy(buffer + start_index, substring, strlen(substring));
    // free substring
    free(substring);
    // compare buffer
    if (strcmp(buffer, str) == 0) {
        printf("Yes\n");
    } else {
        printf("No\n");
    }
}
